import fitz, re
ACK_HEADER_RE = re.compile(r"^\s*(\d+\.?\s*)?acknowledg(e)?ments\b", re.I)
SECTION_RE = re.compile(r"^\s*\d+\.?\s*\S+")
REFERENCES_RE = re.compile(r"^\s*(\d+\.?\s*)?references\b", re.I)

def collect_ack_lines(doc):
    ack_lines = []
    in_ack = False
    for i, page in enumerate(doc):
        lines = page.get_text('text').splitlines()
        for line in lines:
            if ACK_HEADER_RE.match(line.strip()):
                in_ack = True
                if line.strip():
                    ack_lines.append((i, line))
                continue
            if in_ack:
                if REFERENCES_RE.match(line.strip()) or SECTION_RE.match(line.strip()):
                    in_ack = False
                    continue
                if line.strip():
                    ack_lines.append((i, line))
    return ack_lines

path='/root/paper2.pdf'
doc=fitz.open(path)
ack_lines=collect_ack_lines(doc)
# print lines containing names
for pno, line in ack_lines:
    if 'Shengyuan' in line or 'Pengcheng' in line:
        print('LINE:', repr(line))
        page=doc[pno]
        print('search_for line', len(page.search_for(line)))
        print('search_for name', len(page.search_for('Shengyuan Xu')), len(page.search_for('Pengcheng Zhu')))
        break

doc.close()
